1	package web
2	
3	import (
4		"encoding/json"
5		"net/http"
6	
7		"backend_server/internal/services/onboarding"
8		"backend_server/internal/web/middleware"
9	
10		"github.com/gorilla/mux"
11	)
12	
13	// OnboardingHandlers provides HTTP handlers for onboarding
14	type OnboardingHandlers struct {
15		onboardingService *onboarding.OnboardingService
16	}
17	
18	// NewOnboardingHandlers creates new onboarding handlers
19	func NewOnboardingHandlers(onboardingService *onboarding.OnboardingService) *OnboardingHandlers {
20		return &OnboardingHandlers{
21			onboardingService: onboardingService,
22		}
23	}
24	
25	// RegisterRoutes registers onboarding routes
26	func (h *OnboardingHandlers) RegisterRoutes(r *mux.Router, authMiddleware *middleware.AuthMiddleware) {
27		onboardingRouter := r.PathPrefix("/api/onboarding").Subrouter()
28	
29		// Protected routes
30		if authMiddleware != nil {
31			protectedRouter := onboardingRouter.PathPrefix("").Subrouter()
32			protectedRouter.Use(authMiddleware.RequireAuth)
33			protectedRouter.HandleFunc("/organizations", h.OnboardOrganization).Methods("POST", "OPTIONS")
34			protectedRouter.HandleFunc("/organizations", h.ListConfigurations).Methods("GET", "OPTIONS")
35			protectedRouter.HandleFunc("/organizations/{id}", h.GetConfiguration).Methods("GET", "OPTIONS")
36			protectedRouter.HandleFunc("/organizations/{id}", h.UpdateConfiguration).Methods("PUT", "OPTIONS")
37			protectedRouter.HandleFunc("/organizations/{id}", h.DeleteConfiguration).Methods("DELETE", "OPTIONS")
38			protectedRouter.HandleFunc("/organizations/{id}/validate", h.ValidateAction).Methods("POST", "OPTIONS")
39		} else {
40			// No auth required for testnet mode
41			onboardingRouter.HandleFunc("/organizations", h.OnboardOrganization).Methods("POST", "OPTIONS")
42			onboardingRouter.HandleFunc("/organizations", h.ListConfigurations).Methods("GET", "OPTIONS")
43			onboardingRouter.HandleFunc("/organizations/{id}", h.GetConfiguration).Methods("GET", "OPTIONS")
44			onboardingRouter.HandleFunc("/organizations/{id}", h.UpdateConfiguration).Methods("PUT", "OPTIONS")
45			onboardingRouter.HandleFunc("/organizations/{id}", h.DeleteConfiguration).Methods("DELETE", "OPTIONS")
46			onboardingRouter.HandleFunc("/organizations/{id}/validate", h.ValidateAction).Methods("POST", "OPTIONS")
47		}
48	}
49	
50	// OnboardOrganization handles POST /api/onboarding/organizations
51	func (h *OnboardingHandlers) OnboardOrganization(w http.ResponseWriter, r *http.Request) {
52		var req onboarding.OnboardingRequest
53		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
54			http.Error(w, `{"error":"invalid request body"}`, http.StatusBadRequest)
55			return
56		}
57	
58		if req.OrganizationID == "" {
59			http.Error(w, `{"error":"organization_id is required"}`, http.StatusBadRequest)
60			return
61		}
62	
63		result, err := h.onboardingService.OnboardOrganization(r.Context(), &req)
64		if err != nil {
65			http.Error(w, `{"error":"`+err.Error()+`"}`, http.StatusInternalServerError)
66			return
67		}
68	
69		w.Header().Set("Content-Type", "application/json")
70		json.NewEncoder(w).Encode(result)
71	}
72	
73	// ListConfigurations handles GET /api/onboarding/organizations
74	func (h *OnboardingHandlers) ListConfigurations(w http.ResponseWriter, r *http.Request) {
75		configs := h.onboardingService.ListConfigurations()
76		w.Header().Set("Content-Type", "application/json")
77		json.NewEncoder(w).Encode(map[string]interface{}{
78			"configurations": configs,
79			"total":          len(configs),
80		})
81	}
82	
83	// GetConfiguration handles GET /api/onboarding/organizations/{id}
84	func (h *OnboardingHandlers) GetConfiguration(w http.ResponseWriter, r *http.Request) {
85		vars := mux.Vars(r)
86		configID := vars["id"]
87	
88		config, err := h.onboardingService.GetConfiguration(configID)
89		if err != nil {
90			http.Error(w, `{"error":"configuration not found"}`, http.StatusNotFound)
91			return
92		}
93	
94		w.Header().Set("Content-Type", "application/json")
95		json.NewEncoder(w).Encode(config)
96	}
97	
98	// UpdateConfiguration handles PUT /api/onboarding/organizations/{id}
99	func (h *OnboardingHandlers) UpdateConfiguration(w http.ResponseWriter, r *http.Request) {
100		vars := mux.Vars(r)
101		configID := vars["id"]
102	
103		var req onboarding.OnboardingRequest
104		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
105			http.Error(w, `{"error":"invalid request body"}`, http.StatusBadRequest)
106			return
107		}
108	
109		config, err := h.onboardingService.UpdateConfiguration(configID, &req)
110		if err != nil {
111			http.Error(w, `{"error":"`+err.Error()+`"}`, http.StatusInternalServerError)
112			return
113		}
114	
115		w.Header().Set("Content-Type", "application/json")
116		json.NewEncoder(w).Encode(config)
117	}
118	
119	// DeleteConfiguration handles DELETE /api/onboarding/organizations/{id}
120	func (h *OnboardingHandlers) DeleteConfiguration(w http.ResponseWriter, r *http.Request) {
121		vars := mux.Vars(r)
122		configID := vars["id"]
123	
124		if err := h.onboardingService.DeleteConfiguration(configID); err != nil {
125			http.Error(w, `{"error":"`+err.Error()+`"}`, http.StatusInternalServerError)
126			return
127		}
128	
129		w.Header().Set("Content-Type", "application/json")
130		json.NewEncoder(w).Encode(map[string]interface{}{
131			"status":    "deleted",
132			"config_id": configID,
133		})
134	}
135	
136	// ValidateAction handles POST /api/onboarding/organizations/{id}/validate
137	func (h *OnboardingHandlers) ValidateAction(w http.ResponseWriter, r *http.Request) {
138		vars := mux.Vars(r)
