2174	// validateProductionCredentials ensures that either root.key (root node) or
2175	// boot.key (bootnode) is present and valid before the server starts in production
2176	// mode. Returns a non-nil error with a specific, actionable message on failure.
2177	//
2178	// Root node: root.key must exist; warns if ORACLE_KEY_PASSWORD is unset.
2179	// Bootnode: boot.key must decrypt successfully; JWTSecret, CloudflareAPIToken,
2180	// and CloudflareZoneID must be non-empty.
2181	func validateProductionCredentials() error {
2182		rootKeyPath := bootkey.FindRootKey()
2183		bootKeyExists := bootkey.Exists()
2184	
2185		if rootKeyPath == "" && !bootKeyExists {
2186			searched := make([]string, 0, 20)
2187			for _, p := range bootkey.RootKeyCandidatePaths() {
2188				searched = append(searched, "  root.key: "+p)
2189			}
2190			for _, p := range bootkey.CandidatePaths() {
2191				searched = append(searched, "  boot.key: "+p)
2192			}
2193			return fmt.Errorf(
2194				"production mode requires root.key (root node) or boot.key (bootnode).\n"+
2195					"Neither was found in any of these locations:\n%s\n\n"+
2196					"Options:\n"+
2197					"  • Root node:  place root.key in one of the locations above\n"+
2198					"  • Bootnode:   place boot.key in one of the locations above and set BOOT_KEY_PASSWORD\n"+
2199					"  • Testnet:    pass the --testnet flag to bypass credential checks\n"+
2200					"  • Override:   set ORACLE_KEY_PATH or KNIRV_BOOT_KEY_PATH env vars",
2201				strings.Join(searched, "\n"),
2202			)
2203		}
2204	
2205		if rootKeyPath != "" {
2206			if os.Getenv("ORACLE_KEY_PASSWORD") == "" {
2207				log.Printf("[KEY] WARNING: root.key found at %s but ORACLE_KEY_PASSWORD is not set", rootKeyPath)
2208				log.Printf("[KEY]          The oracle service will start degraded — set ORACLE_KEY_PASSWORD to enable it")
2209			} else {
2210				log.Printf("[KEY] Root node credentials: root.key at %s", rootKeyPath)
2211			}
2212			return nil
2213		}
2214	
2215		// Bootnode validation.
2216		if os.Getenv("BOOT_KEY_PASSWORD") == "" {
2217			return fmt.Errorf(
2218				"boot.key found but BOOT_KEY_PASSWORD is not set.\n" +
2219					"Set BOOT_KEY_PASSWORD to the decryption password for boot.key.\n" +
2220					"The server cannot start in production mode without decrypted credentials.",
2221			)
2222		}
2223	
2224		content, err := bootkey.Load()
2225		if err != nil {
2226			return fmt.Errorf(
2227				"boot.key decryption failed: %w\n"+
2228					"Verify BOOT_KEY_PASSWORD is correct for this boot.key file",
2229				err,
2230			)
2231		}
2232	
2233		var missing []string
