2235			missing = append(missing, "JWTSecret (field 10)")
2236		}
2237		if content.CloudflareAPIToken == "" {
2238			missing = append(missing, "CloudflareAPIToken (field 18)")
2239		}
2240		if content.CloudflareZoneID == "" {
2241			missing = append(missing, "CloudflareZoneID (field 19)")
2242		}
2243		if len(missing) > 0 {
2244			return fmt.Errorf(
2245				"boot.key is missing required fields: %s\n"+
2246					"Re-provision boot.key using the KNIRV onboarding CLI.\n"+
2247					"All required fields must be populated before the server can start in production mode.",
2248				strings.Join(missing, ", "),
2249			)
2250		}
2251	
2252		log.Printf("[KEY] Bootnode credentials valid (registration_id=%s)", content.RegistrationID)
