227		for i := 0; i < len(data); {
228			tag, next, e := readVarint(data, i)
229			if e != nil {
230				return nil, nil, e
231			}
232			i = next
233			fieldNum := int(tag >> 3)
234			wireType := int(tag & 0x7)
235			if wireType != 2 {
236				return nil, nil, fmt.Errorf("unexpected wire type %d at field %d in envelope", wireType, fieldNum)
237			}
238			length, next, e := readVarint(data, i)
239			if e != nil {
240				return nil, nil, e
241			}
242			i = next
243			end := i + int(length)
244			if end > len(data) {
245				return nil, nil, fmt.Errorf("truncated field %d in envelope", fieldNum)
246			}
247			switch fieldNum {
248			case 1:
249				encryptedContent = make([]byte, length)
250				copy(encryptedContent, data[i:end])
251			case 2:
252				salt = make([]byte, length)
253				copy(salt, data[i:end])
254			}
255			i = end
256		}
257		if encryptedContent == nil {
258			return nil, nil, fmt.Errorf("boot.key envelope missing encrypted_content")
259		}
260		if salt == nil {
261			return nil, nil, fmt.Errorf("boot.key envelope missing salt")
262		}
263		return encryptedContent, salt, nil
264	}
