266	// extractStringFields walks decrypted inner proto3 bytes and returns all
267	// length-delimited string fields indexed by field number.
268	func extractStringFields(data []byte) (map[int]string, error) {
269		result := make(map[int]string)
270		for i := 0; i < len(data); {
271			tag, next, err := readVarint(data, i)
272			if err != nil {
273				return nil, err
274			}
275			i = next
276			fieldNum := int(tag >> 3)
277			wireType := int(tag & 0x7)
278	
279			switch wireType {
280			case 0: // varint — skip
281				_, next, err = readVarint(data, i)
282				if err != nil {
283					return nil, err
284				}
285				i = next
286			case 1: // 64-bit fixed — skip 8 bytes
287				if i+8 > len(data) {
288					return nil, fmt.Errorf("truncated fixed64 at field %d", fieldNum)
289				}
290				i += 8
291			case 2: // length-delimited
292				length, next, err := readVarint(data, i)
293				if err != nil {
294					return nil, err
295				}
296				i = next
297				end := i + int(length)
298				if end > len(data) {
299					return nil, fmt.Errorf("truncated field %d", fieldNum)
300				}
301				result[fieldNum] = string(data[i:end])
302				i = end
303			case 5: // 32-bit fixed — skip 4 bytes
304				if i+4 > len(data) {
305					return nil, fmt.Errorf("truncated fixed32 at field %d", fieldNum)
306				}
307				i += 4
308			default:
309				return nil, fmt.Errorf("unsupported wire type %d at field %d", wireType, fieldNum)
310			}
311		}
312		return result, nil
313	}
314	
315	func readVarint(data []byte, start int) (uint64, int, error) {
316		var value uint64
317		var shift uint
318		for i := start; i < len(data); i++ {
319			b := data[i]
320			value |= uint64(b&0x7f) << shift
321			if b < 0x80 {
322				return value, i + 1, nil
323			}
324			shift += 7
325			if shift >= 64 {
326				return 0, 0, fmt.Errorf("varint overflow")
327			}
328		}
329		return 0, 0, fmt.Errorf("truncated varint")
330	}
