package badge

// BadgeInfo is the backend-owned badge metadata model used by guardrail and
// ICME wiring. It intentionally stays local to the backend so the build does
// not depend on an external shell module.
type BadgeInfo struct {
	ID                 string             `json:"id"`
	Name               string             `json:"name,omitempty"`
	Description        string             `json:"description,omitempty"`
	AlignmentThreshold float64            `json:"alignment_threshold,omitempty"`
	ValueSignals       []string           `json:"value_signals,omitempty"`
	OntologySignals    []string           `json:"ontology_signals,omitempty"`
	APIKeys            []BadgeAPIKey      `json:"api_keys,omitempty"`
	JWTClaims          []BadgeJWTClaim    `json:"jwt_claims,omitempty"`
	RoleBindings       []BadgeRoleBinding `json:"role_bindings,omitempty"`
	Metadata           map[string]any     `json:"metadata,omitempty"`
}

// BadgeAPIKey captures a badge-scoped API key binding.
type BadgeAPIKey struct {
	KeyID string `json:"key_id,omitempty"`
	Scope string `json:"scope,omitempty"`
}

// BadgeJWTClaim captures the JWT claim payload attached to a badge.
type BadgeJWTClaim struct {
	Action string `json:"action,omitempty"`
	Claim  string `json:"claim,omitempty"`
	Value  string `json:"value,omitempty"`
}

// BadgeRoleBinding captures the role binding payload attached to a badge.
type BadgeRoleBinding struct {
	Role  string `json:"role,omitempty"`
	Scope string `json:"scope,omitempty"`
}

