package badge

import (
	"encoding/json"
	"fmt"
	"log"
	"time"

	"backend_server/internal/database"

	"github.com/google/uuid"
	"github.com/tidwall/buntdb"
)

const badgeKeyPrefix = "badge:registry:"

// BadgeRegistry stores badge definitions in BuntDB and implements
// BadgeRegistryInterface for use by GuardrailInjector and ICMEAlignmentBridge.
type BadgeRegistry struct {
	db *database.BuntDBManager
}

// NewBadgeRegistry creates a BuntDB-backed badge registry.
func NewBadgeRegistry(db *database.BuntDBManager) *BadgeRegistry {
	return &BadgeRegistry{db: db}
}

// StoreBadge persists a badge definition. If badge.ID is empty a new UUID is assigned.
func (r *BadgeRegistry) StoreBadge(b *BadgeInfo) error {
	if b.ID == "" {
		b.ID = uuid.New().String()
	}
	if ts, ok := b.Metadata["created_at"]; !ok || ts == nil {
		if b.Metadata == nil {
			b.Metadata = make(map[string]interface{})
		}
		b.Metadata["created_at"] = time.Now().UTC().Format(time.RFC3339)
	}

	data, err := json.Marshal(b)
	if err != nil {
		return fmt.Errorf("marshal badge: %w", err)
	}

	return r.db.Transaction(func(tx *buntdb.Tx) error {
		_, _, err := tx.Set(badgeKeyPrefix+b.ID, string(data), nil)
		return err
	})
}

// GetBadge retrieves a badge by ID. Implements BadgeRegistryInterface.
func (r *BadgeRegistry) GetBadge(badgeID string) (*BadgeInfo, error) {
	var b BadgeInfo
	err := r.db.ViewTransaction(func(tx *buntdb.Tx) error {
		val, err := tx.Get(badgeKeyPrefix + badgeID)
		if err != nil {
			return fmt.Errorf("badge not found: %s", badgeID)
		}
		return json.Unmarshal([]byte(val), &b)
	})
	if err != nil {
		return nil, err
	}
	return &b, nil
}

// ListBadges returns all stored badges.
func (r *BadgeRegistry) ListBadges() ([]*BadgeInfo, error) {
	var badges []*BadgeInfo
	err := r.db.GetObjectsByPrefix(badgeKeyPrefix, func(key string, value []byte) bool {
		var b BadgeInfo
		if err := json.Unmarshal(value, &b); err != nil {
			log.Printf("[badge-registry] skip corrupt entry %s: %v", key, err)
			return true
		}
		badges = append(badges, &b)
		return true
	})
	return badges, err
}

// DeleteBadge removes a badge definition. Returns error if not found.
func (r *BadgeRegistry) DeleteBadge(badgeID string) error {
	return r.db.Transaction(func(tx *buntdb.Tx) error {
		_, err := tx.Delete(badgeKeyPrefix + badgeID)
		if err != nil {
			return fmt.Errorf("badge not found: %s", badgeID)
		}
		return nil
	})
}

