package dvemanager

import (
	"fmt"
	"log"
	"time"

	"github.com/tidwall/buntdb"
)

// AttachBadge records a badge→DVE enforcement binding in BuntDB and updates the
// DVENode's AttachedBadges list. Returns error if the node does not exist.
func (dm *DVEManager) AttachBadge(nodeID, badgeID string) error {
	dm.mu.Lock()
	defer dm.mu.Unlock()

	node, err := dm.getNodeFromDB(nodeID)
	if err != nil {
		return fmt.Errorf("node %s not found: %w", nodeID, err)
	}

	// Idempotent — skip if already attached.
	for _, id := range node.AttachedBadges {
		if id == badgeID {
			return nil
		}
	}

	node.AttachedBadges = append(node.AttachedBadges, badgeID)
	node.UpdatedAt = time.Now()

	if err := dm.storeNode(node); err != nil {
		return fmt.Errorf("store node after badge attach: %w", err)
	}

	// Persist the binding keyed separately for fast reverse lookups.
	if err := dm.db.Transaction(func(tx *buntdb.Tx) error {
		_, _, err := tx.Set(fmt.Sprintf("badge:binding:%s:%s", nodeID, badgeID), badgeID, nil)
		return err
	}); err != nil {
		log.Printf("[dve-badges] warn: could not persist binding key for badge %s on %s: %v", badgeID, nodeID, err)
	}

	log.Printf("[dve-badges] badge %s attached to DVE %s", badgeID, nodeID)
	return nil
}

// DetachBadge removes a badge→DVE enforcement binding from BuntDB and the DVENode.
func (dm *DVEManager) DetachBadge(nodeID, badgeID string) error {
	dm.mu.Lock()
	defer dm.mu.Unlock()

	node, err := dm.getNodeFromDB(nodeID)
	if err != nil {
		return fmt.Errorf("node %s not found: %w", nodeID, err)
	}

	remaining := node.AttachedBadges[:0]
	found := false
	for _, id := range node.AttachedBadges {
		if id == badgeID {
			found = true
		} else {
			remaining = append(remaining, id)
		}
	}
	if !found {
		return fmt.Errorf("badge %s not attached to DVE %s", badgeID, nodeID)
	}

	node.AttachedBadges = remaining
	node.UpdatedAt = time.Now()

	if err := dm.storeNode(node); err != nil {
		return fmt.Errorf("store node after badge detach: %w", err)
	}

	_ = dm.db.Transaction(func(tx *buntdb.Tx) error {
		_, err := tx.Delete(fmt.Sprintf("badge:binding:%s:%s", nodeID, badgeID))
		return err
	})

	log.Printf("[dve-badges] badge %s detached from DVE %s", badgeID, nodeID)
	return nil
}

// GetAttachedBadges returns the list of badge IDs currently attached to a DVE.
func (dm *DVEManager) GetAttachedBadges(nodeID string) ([]string, error) {
	node, err := dm.getNodeFromDB(nodeID)
	if err != nil {
		return nil, fmt.Errorf("node %s not found: %w", nodeID, err)
	}
	return node.AttachedBadges, nil
}

