package icme

import (
	"log"
	"time"

	"backend_server/internal/services/badge"
)

// IngestBadgeSignal implements badge.AlignmentSink.
// It translates a BadgeValueSignal into an alignment record and stores it via
// the IntentRegistry so badge-value drift appears in the standard alignment view.
func (s *Service) IngestBadgeSignal(signal *badge.BadgeValueSignal) error {
	rec := &AlignmentRecord{
		AgentID:        "badge:" + signal.BadgeID,
		DVEID:          signal.DVEID,
		ObjectiveName:  "badge-alignment",
		Decision:       "approved",
		Outcome:        "badge_attached",
		AlignmentScore: signal.AlignmentThreshold,
		FidelityScore:  signal.AlignmentThreshold,
		Timestamp:      time.Now(),
	}

	if err := s.intentRegistry.RecordAlignment(rec); err != nil {
		log.Printf("[icme-badge-sink] failed to record badge alignment for %s/%s: %v",
			signal.BadgeID, signal.DVEID, err)
		return err
	}

	log.Printf("[icme-badge-sink] badge %s ingested for DVE %s (threshold=%.2f, tags=%v)",
		signal.BadgeID, signal.DVEID, signal.AlignmentThreshold, signal.ValueSignals)
	return nil
}

