	"net/http"

	"backend_server/internal/services/badge"
	"backend_server/internal/services/dvemanager"

	"github.com/gorilla/mux"
)

// BadgeHandlers provides HTTP handlers for badge lifecycle and DVE attachment operations.
type BadgeHandlers struct {
	registry   *badge.BadgeRegistry
	dveManager *dvemanager.DVEManager    // nil-safe
	injector   *badge.GuardrailInjector  // nil-safe
	icmeBridge *badge.ICMEAlignmentBridge // nil-safe
}

// NewBadgeHandlers creates badge-specific HTTP handlers.
func NewBadgeHandlers(
	registry *badge.BadgeRegistry,
	dveManager *dvemanager.DVEManager,
	injector *badge.GuardrailInjector,
	icmeBridge *badge.ICMEAlignmentBridge,
) *BadgeHandlers {
	return &BadgeHandlers{
		registry:   registry,
		dveManager: dveManager,
		injector:   injector,
		icmeBridge: icmeBridge,
	}
}

// RegisterRoutes attaches badge and DVE-attachment endpoints to the router.
// All routes are prefixed with /api/badge or /api/dve/{nodeID}/badges.
func (h *BadgeHandlers) RegisterRoutes(r *mux.Router) {
	r.HandleFunc("/api/badge/generate", h.GenerateBadgeSVG).Methods("POST", "OPTIONS")
	r.HandleFunc("/api/badge/create", h.CreateBadge).Methods("POST", "OPTIONS")
	r.HandleFunc("/api/badge/{id}", h.GetBadge).Methods("GET", "OPTIONS")
	r.HandleFunc("/api/badge", h.ListBadges).Methods("GET", "OPTIONS")
	r.HandleFunc("/api/badge/{id}", h.DeleteBadge).Methods("DELETE", "OPTIONS")

	r.HandleFunc("/api/dve/{nodeID}/badges", h.AttachBadge).Methods("POST", "OPTIONS")
	r.HandleFunc("/api/dve/{nodeID}/badges/{badgeID}", h.DetachBadge).Methods("DELETE", "OPTIONS")
	r.HandleFunc("/api/dve/{nodeID}/badges", h.GetAttachedBadges).Methods("GET", "OPTIONS")
}

// GenerateBadgeSVG handles POST /api/badge/generate.
func (h *BadgeHandlers) GenerateBadgeSVG(w http.ResponseWriter, r *http.Request) {
	if r.Method == "OPTIONS" {
		w.WriteHeader(http.StatusOK)
		return
	}

	var params badge.BadgeSVGParams
	if err := json.NewDecoder(r.Body).Decode(&params); err != nil {
		http.Error(w, `{"error":"invalid request body"}`, http.StatusBadRequest)
		return
	}
	if params.Name == "" {
		params.Name = "KNIRV Badge"
	}
	if params.OutputSize <= 0 {
		params.OutputSize = 400
	}

	svg := badge.GenerateBadgeSVG(params)
	w.Header().Set("Content-Type", "image/svg+xml")
	w.Header().Set("Cache-Control", "public, max-age=3600")
	w.Write([]byte(svg))
}

// CreateBadge handles POST /api/badge/create.
// Body: BadgeInfo JSON (id, name, description, alignment_threshold, value_signals,
//
//	ontology_signals, api_keys, jwt_claims, role_bindings, metadata).
//
// (4.6) — stores auth credential fields from BadgeCreateRequest.Metadata.
func (h *BadgeHandlers) CreateBadge(w http.ResponseWriter, r *http.Request) {
	if r.Method == "OPTIONS" {
		w.WriteHeader(http.StatusOK)
		return
	}

	var b badge.BadgeInfo
	if err := json.NewDecoder(r.Body).Decode(&b); err != nil {
		http.Error(w, `{"error":"invalid request body"}`, http.StatusBadRequest)
		return
	}
	if b.Name == "" {
		http.Error(w, `{"error":"name is required"}`, http.StatusBadRequest)
		return
	}

	if err := h.registry.StoreBadge(&b); err != nil {
		http.Error(w, `{"error":"failed to store badge"}`, http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(b)
}

// GetBadge handles GET /api/badge/{id}.
func (h *BadgeHandlers) GetBadge(w http.ResponseWriter, r *http.Request) {
	if r.Method == "OPTIONS" {
		w.WriteHeader(http.StatusOK)
		return
	}
	badgeID := mux.Vars(r)["id"]
	b, err := h.registry.GetBadge(badgeID)
	if err != nil {
		http.Error(w, `{"error":"badge not found"}`, http.StatusNotFound)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(b)
}

// ListBadges handles GET /api/badge.
func (h *BadgeHandlers) ListBadges(w http.ResponseWriter, r *http.Request) {
	if r.Method == "OPTIONS" {
		w.WriteHeader(http.StatusOK)
		return
	}
	badges, err := h.registry.ListBadges()
	if err != nil {
		http.Error(w, `{"error":"failed to list badges"}`, http.StatusInternalServerError)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]interface{}{
		"badges": badges,
		"total":  len(badges),
	})
}

// DeleteBadge handles DELETE /api/badge/{id}.
func (h *BadgeHandlers) DeleteBadge(w http.ResponseWriter, r *http.Request) {
	if r.Method == "OPTIONS" {
		w.WriteHeader(http.StatusOK)
		return
	}
	badgeID := mux.Vars(r)["id"]
	if err := h.registry.DeleteBadge(badgeID); err != nil {
		http.Error(w, `{"error":"badge not found"}`, http.StatusNotFound)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]string{"status": "deleted", "badge_id": badgeID})
}

// AttachBadge handles POST /api/dve/{nodeID}/badges.
// Body: {"badge_id": "<id>"}
// (4.7) — persists badge:binding:{dveID}:{badgeID} in BuntDB, injects guardrail rules,
// and registers badge value signals with ICME.
func (h *BadgeHandlers) AttachBadge(w http.ResponseWriter, r *http.Request) {
	if r.Method == "OPTIONS" {
		w.WriteHeader(http.StatusOK)
		return
	}

	nodeID := mux.Vars(r)["nodeID"]

	var req struct {
		BadgeID string `json:"badge_id"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil || req.BadgeID == "" {
		http.Error(w, `{"error":"badge_id is required"}`, http.StatusBadRequest)
		return
	}

	b, err := h.registry.GetBadge(req.BadgeID)
	if err != nil {
		http.Error(w, `{"error":"badge not found"}`, http.StatusNotFound)
		return
	}

	if h.dveManager != nil {
		if err := h.dveManager.AttachBadge(nodeID, req.BadgeID); err != nil {
			http.Error(w, `{"error":"`+err.Error()+`"}`, http.StatusBadRequest)
			return
		}
	}

	// Inject guardrail rules for the badge's ontology signals (4.7, 4.11).
	if h.injector != nil {
		if err := h.injector.AttachBadge(nodeID, req.BadgeID); err != nil {
			// Non-fatal: log and continue; DVE binding is already persisted.
			_ = err
		}
	}

	// Register badge value signals with the ICME alignment loop (4.8).
	if h.icmeBridge != nil {
		if err := h.icmeBridge.OnBadgeAttached(nodeID, req.BadgeID); err != nil {
			_ = err
		}
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]interface{}{
		"status":   "attached",
		"dve_id":   nodeID,
		"badge_id": req.BadgeID,
		"badge":    b,
	})
}

// DetachBadge handles DELETE /api/dve/{nodeID}/badges/{badgeID}.
// (4.7, 4.14) — removes the binding from BuntDB, clears guardrail rules.
func (h *BadgeHandlers) DetachBadge(w http.ResponseWriter, r *http.Request) {
	if r.Method == "OPTIONS" {
		w.WriteHeader(http.StatusOK)
		return
	}

	vars := mux.Vars(r)
	nodeID := vars["nodeID"]
	badgeID := vars["badgeID"]

	if h.dveManager != nil {
		if err := h.dveManager.DetachBadge(nodeID, badgeID); err != nil {
			http.Error(w, `{"error":"`+err.Error()+`"}`, http.StatusBadRequest)
			return
		}
	}

	if h.injector != nil {
		h.injector.DetachBadge(nodeID, badgeID)
	}
	if h.icmeBridge != nil {
		h.icmeBridge.OnBadgeDetached(nodeID, badgeID)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]string{
		"status":   "detached",
		"dve_id":   nodeID,
		"badge_id": badgeID,
	})
}

// GetAttachedBadges handles GET /api/dve/{nodeID}/badges.
// Returns the list of attached badge IDs and their full definitions.
// (4.12, 4.14) — badge status + enforcement state endpoint.
func (h *BadgeHandlers) GetAttachedBadges(w http.ResponseWriter, r *http.Request) {
	if r.Method == "OPTIONS" {
		w.WriteHeader(http.StatusOK)
		return
	}

	nodeID := mux.Vars(r)["nodeID"]

	var badgeIDs []string
	if h.dveManager != nil {
		var err error
		badgeIDs, err = h.dveManager.GetAttachedBadges(nodeID)
		if err != nil {
			http.Error(w, `{"error":"node not found"}`, http.StatusNotFound)
			return
		}
	}

	// Fetch full badge info for each ID.
	type badgeStatus struct {
		*badge.BadgeInfo
		EnforcementActive bool `json:"enforcement_active"`
	}
	var result []badgeStatus
	for _, id := range badgeIDs {
		b, err := h.registry.GetBadge(id)
		if err != nil {
			b = &badge.BadgeInfo{ID: id, Name: "(unknown)"}
		}
		active := h.injector != nil && h.injector.IsAttached(nodeID, id)
		result = append(result, badgeStatus{BadgeInfo: b, EnforcementActive: active})
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]interface{}{
		"dve_id": nodeID,
		"badges": result,
		"total":  len(result),
	})
}

